const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws);

// --- Analysis ---
const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');

const totalRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s, r) => s + r['Total Paid'], 0);

// Per customer
const custMap = {};
data.forEach(r => {
  if (!custMap[r.Customer]) custMap[r.Customer] = {orders: 0, confirmed: 0, cancelled: 0, revenue: 0};
  custMap[r.Customer].orders++;
  if (r.Status === 'confirmed') { custMap[r.Customer].confirmed++; custMap[r.Customer].revenue += r['Total Paid']; }
  else custMap[r.Customer].cancelled++;
});

// Items frequency (confirmed only)
const itemMap = {};
confirmed.forEach(r => {
  r.Items.split(',').map(i => i.trim()).forEach(i => { itemMap[i] = (itemMap[i] || 0) + 1; });
});
const topItems = Object.entries(itemMap).sort((a,b) => b[1] - a[1]);

// Date range
const dates = [...new Set(data.map(r => r.Date))].sort();

console.log('=== ORDER ANALYSIS ===');
console.log('Date range:', dates[0], 'to', dates[dates.length-1]);
console.log('Total orders:', totalOrders);
console.log('Confirmed:', confirmed.length, '(' + (confirmed.length/totalOrders*100).toFixed(1) + '%)');
console.log('Cancelled:', cancelled.length, '(' + (cancelled.length/totalOrders*100).toFixed(1) + '%)');
console.log('Total confirmed revenue: \$' + totalRevenue.toFixed(2));
console.log('Lost to cancellations: \$' + cancelledValue.toFixed(2));
console.log('Avg confirmed order value: \$' + (totalRevenue / confirmed.length).toFixed(2));
console.log();
console.log('=== PER CUSTOMER ===');
Object.entries(custMap).sort((a,b) => b[1].revenue - a[1].revenue).forEach(([c, v]) => {
  console.log(c + ': ' + v.orders + ' orders (' + v.confirmed + ' confirmed, ' + v.cancelled + ' cancelled) — revenue \$' + v.revenue.toFixed(2));
});
console.log();
console.log('=== TOP ITEMS (confirmed) ===');
topItems.forEach(([item, count]) => console.log(count + 'x ' + item));
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const docx = require('docx');
const fs = require('fs');

const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);

const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s, r) => s + r['Total Paid'], 0);
const dates = [...new Set(data.map(r => r.Date))].sort();

// Per-customer stats
const custMap = {};
data.forEach(r => {
  if (!custMap[r.Customer]) custMap[r.Customer] = {orders:0, confirmed:0, cancelled:0, revenue:0};
  custMap[r.Customer].orders++;
  if (r.Status === 'confirmed') { custMap[r.Customer].confirmed++; custMap[r.Customer].revenue += r['Total Paid']; }
  else custMap[r.Customer].cancelled++;
});
const custSorted = Object.entries(custMap).sort((a,b) => b[1].revenue - a[1].revenue);

// Items frequency
const itemMap = {};
confirmed.forEach(r => r.Items.split(',').map(i => i.trim()).forEach(i => { itemMap[i] = (itemMap[i]||0)+1; }));
const topItems = Object.entries(itemMap).sort((a,b) => b[1]-a[1]);

// ----- Build Word Doc -----
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, HeadingLevel, AlignmentType, BorderStyle } = docx;

const headerCell = (text) => new TableCell({
  children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: 'Calibri' })], alignment: AlignmentType.CENTER })],
  shading: { fill: '2E86C1', color: 'FFFFFF' },
  verticalAlign: 'center',
});
const cell = (text, align) => new TableCell({
  children: [new Paragraph({ children: [new TextRun({ text: String(text), size: 20, font: 'Calibri' })], alignment: align || AlignmentType.LEFT })],
  verticalAlign: 'center',
});

const custRows = [
  new TableRow({ children: ['Customer','Orders','Confirmed','Cancelled','Revenue'].map(headerCell) }),
  ...custSorted.map(([c,v]) => new TableRow({ children: [
    cell(c), cell(String(v.orders), AlignmentType.CENTER), cell(String(v.confirmed), AlignmentType.CENTER),
    cell(String(v.cancelled), AlignmentType.CENTER), cell('\$'+v.revenue.toFixed(2), AlignmentType.RIGHT)
  ]}))
];

const itemRows = [
  new TableRow({ children: ['Product','Times Ordered'].map(headerCell) }),
  ...topItems.map(([item,count]) => new TableRow({ children: [cell(item), cell(String(count), AlignmentType.CENTER)] }))
];

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: 'Order Summary Analysis', bold: true })] }),
      new Paragraph({ children: [new TextRun({ text: 'Date range: ' + dates[0] + ' to ' + dates[dates.length-1], italics: true, size: 22, font: 'Calibri' })] }),
      new Paragraph({ text: '' }),

      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Overview', bold: true })] }),
      ...[
        'Total orders: ' + data.length,
        'Confirmed: ' + confirmed.length + ' (' + (confirmed.length/data.length*100).toFixed(1) + '%)',
        'Cancelled: ' + cancelled.length + ' (' + (cancelled.length/data.length*100).toFixed(1) + '%)',
        'Confirmed revenue: \$' + totalRevenue.toFixed(2),
        'Lost to cancellations: \$' + cancelledValue.toFixed(2),
        'Average confirmed order value: \$' + (totalRevenue/confirmed.length).toFixed(2),
      ].map(t => new Paragraph({ children: [new TextRun({ text: '• ' + t, size: 22, font: 'Calibri' })], spacing: { after: 60 } })),

      new Paragraph({ text: '' }),
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Revenue by Customer', bold: true })] }),
      new Table({ rows: custRows, width: { size: 100, type: WidthType.PERCENTAGE } }),

      new Paragraph({ text: '' }),
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Top Products (Confirmed Orders)', bold: true })] }),
      new Table({ rows: itemRows, width: { size: 100, type: WidthType.PERCENTAGE } }),

      new Paragraph({ text: '' }),
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Key Takeaways', bold: true })] }),
      ...[
        'The confirmation rate is strong at 88.9%, with only 3 orders cancelled out of 27.',
        'Maya Chen is the top customer by both order count (7) and revenue (\$477), though she also has 2 cancellations.',
        'LogiTech Wireless Mouse M310 is by far the most popular product, appearing in 13 of 24 confirmed orders.',
        'OXO SoftWorks 3-Piece Mixing Bowl Set is the second most popular item (7 orders), often bundled with the mouse.',
        'All orders fall within a narrow 3-day window (Sep 2–4, 2026).',
      ].map(t => new Paragraph({ children: [new TextRun({ text: '• ' + t, size: 22, font: 'Calibri' })], spacing: { after: 80 } })),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/workspace/data/order_analysis.docx', buf);
  console.log('✅ Saved to /workspace/data/order_analysis.docx (' + buf.length + ' bytes)');
});
"
